<?php
declare(strict_types=1);
// The imported fixture creates a fresh random database on the explicitly configured local test server.
require __DIR__.'/document-freeform-native.php';
require_once __DIR__.'/../api/lib/TourLibrary.php';
$clone=QuoteReuse::clone($db,$user,(int)v2v()['id'],(int)v2v()['inquiry_id'],'FULL_DRAFT');$qvid=(int)$clone['version_id'];
