$companyImage=MediaLibrary::ingest($db,$cfg,$user,$bytes,['title'=>'Program public landscape','visibility'=>'COMPANY']);$companyId=(int)$companyImage['asset']['id'];MediaLibrary::review($db,$user,$companyId,['status'=>'APPROVED']);
$doc=['schema'=>'VTA_DOC_2','title'=>'Library Word master','content'=>['type'=>'doc','content'=>[$p('MASTER PROGRAM PROSE'),['type'=>'table','content'=>[['type'=>'tableRow','content'=>[$cell('09:00'),$cell('Hanoi visit')]]]],['type'=>'image','attrs'=>['assetId'=>$companyId,'width'=>320]],['type'=>'table','attrs'=>['vtaSection'=>'pricing'],'content'=>[['type'=>'tableRow','content'=>[$cell('UNREVIEWED_PRICE_CANARY')]]]]]]];
$created=TourLibrary::save($db,$user,['title'=>'Reusable Hanoi','destination'=>'Hanoi','language'=>'en','status'=>'ACTIVE','days'=>[],'proposal'=>['tour_code'=>'VTA-NATIVE','tour_type'=>'PRIVATE','document'=>$doc]]);$programId=(int)$created['id'];
